package mz.bam.seeky.android;
import android.content.*;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;
/** Visual guide with a right-hand drag handle; normal text gestures pass through. */
final class ReaderRuler extends View {
 final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);float fraction;boolean dragging;
 ReaderRuler(Context c){super(c);fraction=c.getSharedPreferences("seeky",0).getFloat("reader_ruler_y",.42f);setContentDescription(AppLanguage.text(c,"Régua de leitura. Arraste o puxador à direita."));setFocusable(true);refresh();}
 void refresh(){setVisibility(getContext().getSharedPreferences("seeky",0).getBoolean("reader_ruler",false)?VISIBLE:GONE);invalidate();}
 protected void onDraw(Canvas canvas){float y=getHeight()*fraction,half=PlusUi.dp(getContext(),27);paint.setColor(0x55000000);canvas.drawRect(0,0,getWidth(),Math.max(0,y-half),paint);canvas.drawRect(0,Math.min(getHeight(),y+half),getWidth(),getHeight(),paint);paint.setColor(AppPalette.of(getContext()).accent);paint.setStrokeWidth(PlusUi.dp(getContext(),1));canvas.drawLine(0,y-half,getWidth(),y-half,paint);canvas.drawLine(0,y+half,getWidth(),y+half,paint);paint.setStrokeWidth(PlusUi.dp(getContext(),4));canvas.drawLine(getWidth()-PlusUi.dp(getContext(),18),y-PlusUi.dp(getContext(),12),getWidth()-PlusUi.dp(getContext(),18),y+PlusUi.dp(getContext(),12),paint);}
 public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){dragging=e.getX()>getWidth()-PlusUi.dp(getContext(),42)&&Math.abs(e.getY()-getHeight()*fraction)<PlusUi.dp(getContext(),36);if(!dragging)return false;getParent().requestDisallowInterceptTouchEvent(true);}if(!dragging)return false;if(e.getActionMasked()==MotionEvent.ACTION_MOVE){fraction=Math.max(.08f,Math.min(.92f,e.getY()/Math.max(1,getHeight())));invalidate();}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){dragging=false;getContext().getSharedPreferences("seeky",0).edit().putFloat("reader_ruler_y",fraction).apply();getParent().requestDisallowInterceptTouchEvent(false);}return true;}
 public void onInitializeAccessibilityNodeInfo(AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(info);info.setScrollable(true);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_FORWARD);info.addAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SCROLL_BACKWARD);}
 public boolean performAccessibilityAction(int action,Bundle args){if(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD||action==AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD){fraction=Math.max(.08f,Math.min(.92f,fraction+(action==AccessibilityNodeInfo.ACTION_SCROLL_FORWARD?.1f:-.1f)));invalidate();return true;}return super.performAccessibilityAction(action,args);}
}
